function validate([cost]) {
  if (!Array.isArray(cost) || cost.length < 1 || cost.length > 12) return 'cost needs 1 to 12 rows.';
  const cols = Array.isArray(cost[0]) ? cost[0].length : 0;
  if (cols < 1 || cols > 12) return 'Each row needs 1 to 12 values.';
  if (cost.some(row => !Array.isArray(row) || row.length !== cols)) return 'All rows must have the same length.';
  if (cost.length < cols) return 'The first group (rows) must be at least as large as the second (columns).';
  if (cost.some(row => row.some(v => !Number.isInteger(v) || v < 0 || v > 100))) return 'Each cost is an integer from 0 to 100.';
  return null;
}

