function connectTwoGroups(cost) {
  const rows = cost.length;
  const cols = cost[0].length;
  const full = 1 << cols;
  const cheapest = new Array(cols).fill(Infinity);
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      cheapest[j] = Math.min(cheapest[j], cost[i][j]);
    }
  }

  let dp = new Array(full).fill(Infinity);
  dp[0] = 0;
  for (let i = 0; i < rows; i++) {
    const next = new Array(full).fill(Infinity);
    for (let mask = 0; mask < full; mask++) {
      if (dp[mask] === Infinity) continue;
      for (let j = 0; j < cols; j++) {
        const joined = mask | (1 << j);
        next[joined] = Math.min(next[joined], dp[mask] + cost[i][j]);
      }
    }
    dp = next;
  }

  let best = Infinity;
  for (let mask = 0; mask < full; mask++) {
    let total = dp[mask];
    for (let j = 0; j < cols; j++) {
      if ((mask & (1 << j)) === 0) total += cheapest[j];
    }
    best = Math.min(best, total);
  }
  return best;
}

