function connectTwoGroups(cost) {
  // Let each left point take any non-empty set of right points and search every choice row by row.
  const rows = cost.length, cols = cost[0].length, full = 1 << cols;
  const memo = new Map();
  const solve = (i, mask) => {
    if (i === rows) return mask === full - 1 ? 0 : Infinity;
    const key = i * full + mask;
    if (memo.has(key)) return memo.get(key);
    let best = Infinity;
    for (let pick = 1; pick < full; pick++) {
      let price = 0;
      for (let j = 0; j < cols; j++) if (pick & (1 << j)) price += cost[i][j];
      best = Math.min(best, price + solve(i + 1, mask | pick));
    }
    memo.set(key, best);
    return best;
  };
  return solve(0, 0);
}

