function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const cols = int(10, 12);
    const rows = int(cols, 12);
    const top = rand() < 0.5 ? 100 : 10;
    return [Array.from({ length: rows }, () => Array.from({ length: cols }, () => int(0, top)))];
  }
  // Small: few columns so the brute force can try every set of columns for every row.
  const cols = int(1, 4);
  const rows = int(cols, 6);
  const top = [3, 10, 100][int(0, 2)];
  return [Array.from({ length: rows }, () => Array.from({ length: cols }, () => int(0, top)))];
}
